// Функция для установки состояния одного бита (светодиода)
void setLedState(int ledIndex, bool state) {
  if (ledIndex < 0 || ledIndex >= TOTAL_LEDS) {
    return; // Выход за пределы
  }

  int byteIndex = ledIndex / 8;     // Номер байта в массиве ledStates
  int bitIndex = ledIndex % 8;      // Номер бита в байтe

  if (byteIndex >= NUM_SHIFT_REGISTERS) {
    return; // Выход за пределы массива
  }

  if (state) {
    ledStates[byteIndex] |= (1 << bitIndex); // Установить бит в 1
  } else {
    ledStates[byteIndex] &= ~(1 << bitIndex); // Установить бит в 0
  }
}

// Функция для очистки всех светодиодов
void clearLEDs() {
